import json
import subprocess

# Load the exact query vector generated by Ollama in TC-02
with open("scripts/tc02_execution_result.json", "r", encoding="utf-8") as f:
    data = json.load(f)

run_data = data["data"]["resultData"]["runData"]
vector = run_data["Ollama Query Embedder"][0]["data"]["main"][0][0]["json"]["embedding"]
vector_str = "[" + ",".join(str(x) for x in vector) + "]"

query = f"""
SELECT 
    id,
    session_id,
    stream_type,
    LEFT(content, 60) AS content_preview,
    ROUND((1 - (embedding <=> '{vector_str}'::vector))::numeric, 4) AS similarity
FROM knowledge_vault
ORDER BY similarity DESC;
"""

res = subprocess.run(
    ['docker', 'exec', 'genx-postgres', 'psql', '-U', 'genx', '-d', 'genx_rag', '-c', query],
    capture_output=True, text=True, check=True
)
print(res.stdout)

# Also run with -t -A -F '|' to parse structured JSON report
res_parse = subprocess.run(
    ['docker', 'exec', 'genx-postgres', 'psql', '-U', 'genx', '-d', 'genx_rag', '-t', '-A', '-F', '|', '-c', query],
    capture_output=True, text=True, check=True
)

rows = []
for line in res_parse.stdout.strip().split('\n'):
    if line.strip():
        parts = line.strip().split('|')
        if len(parts) >= 5:
            rows.append({
                "id": int(parts[0]),
                "session_id": parts[1],
                "stream_type": parts[2],
                "content_preview": parts[3],
                "similarity": float(parts[4])
            })

report = {
    "stage": "Stage 6.2C — TC-02 Cosine Similarity Diagnostic Report",
    "query": "How do I practice Completion with Integrity when closing projects?",
    "framework_threshold": 0.70,
    "voice_threshold": 0.65,
    "total_chunks_evaluated": len(rows),
    "all_chunks_ranked": rows,
    "top_framework_chunk": next((r for r in rows if r["stream_type"] == "framework"), None),
    "top_voice_chunk": next((r for r in rows if r["stream_type"] == "voice_sample"), None)
}

with open("scripts/tc02_similarity_diagnostic_report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)
print("Saved diagnostic report to scripts/tc02_similarity_diagnostic_report.json")

